import React from 'react';

function CarouselControls({ totalSlides, activeIndex, onPrev, onNext, onGoTo }) {
  return (
    <div className="carousel-controls" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '12px', padding: '12px 0' }}>
      <button onClick={onPrev} style={{ padding: '6px 14px', cursor: 'pointer' }}>
        Prev
      </button>
      <div className="carousel-dots" style={{ display: 'flex', gap: '6px' }}>
        {Array.from({ length: totalSlides }, (_, i) => (
          <button
            key={i}
            onClick={() => onGoTo(i)}
            aria-label={`Go to slide ${i + 1}`}
            style={{
              width: '12px',
              height: '12px',
              borderRadius: '50%',
              border: '1px solid #333',
              backgroundColor: i + 1 === activeIndex ? '#333' : '#ccc',
              cursor: 'pointer',
              padding: 0
            }}
          />
        ))}
      </div>
      <button onClick={onNext} style={{ padding: '6px 14px', cursor: 'pointer' }}>
        Next
      </button>
    </div>
  );
}

export default CarouselControls;

