import { describe, test, expect } from 'vitest';
import { render, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

describe('Image Carousel', () => {
  test('renders the first slide by default', () => {
    const { getByText } = render(<App />);
    const heading = getByText('Mountain Sunrise');
    if (!heading) throw new Error('Expected first slide title "Mountain Sunrise" to be visible');
  });

  test('clicking Next advances to the second slide', () => {
    const { getByText } = render(<App />);
    const nextBtn = getByText('Next');
    fireEvent.click(nextBtn);
    const heading = getByText('Ocean Waves');
    if (!heading) throw new Error('Expected second slide title "Ocean Waves" after clicking Next');
  });

  test('clicking Previous from first slide wraps to the last slide', () => {
    const { getByText } = render(<App />);
    const prevBtn = getByText('Prev');
    fireEvent.click(prevBtn);
    const heading = getByText('Forest Trail');
    if (!heading) throw new Error('Expected last slide title "Forest Trail" after clicking Prev from first slide (wrap-around)');
  });

  test('clicking Next on the last slide wraps to the first slide', () => {
    const { getByText } = render(<App />);
    const nextBtn = getByText('Next');
    for (let i = 0; i < 5; i++) {
      fireEvent.click(nextBtn);
    }
    const heading = getByText('Mountain Sunrise');
    if (!heading) throw new Error('Expected first slide "Mountain Sunrise" after advancing past the last slide (wrap-around)');
  });

  test('active dot indicator matches the current slide', () => {
    const { container, getByText } = render(<App />);
    const nextBtn = getByText('Next');
    fireEvent.click(nextBtn);
    const dots = container.querySelectorAll('.carousel-dots button');
    if (dots.length !== 5) throw new Error(`Expected 5 dot buttons, found ${dots.length}`);
    const secondDot = dots[1];
    if (!secondDot) throw new Error('Could not find second dot button');
    const bg = secondDot.style.backgroundColor;
    if (bg !== 'rgb(51, 51, 51)' && bg !== '#333') {
      throw new Error(`Expected second dot to be active (dark background), but got backgroundColor: "${bg}"`);
    }
  });

  test('clicking a specific dot jumps to that slide', () => {
    const { container, getByText } = render(<App />);
    const dots = container.querySelectorAll('.carousel-dots button');
    if (dots.length !== 5) throw new Error(`Expected 5 dot buttons, found ${dots.length}`);
    fireEvent.click(dots[2]);
    const heading = getByText('Desert Dunes');
    if (!heading) throw new Error('Expected third slide "Desert Dunes" after clicking third dot');
  });
});
